{
  "format": "genereti-guide",
  "version": 1,
  "id": "audio-analysis",
  "title": "See sound, use sound",
  "summary": "Scopes, spectral analysis, stereo geometry and audio-driven visual controls.",
  "steps": [
    {
      "title": "Start the patch",
      "text": "Press ▷ on mod.output. Sound starts explicitly at a low level. The analysis taps remain silent until their source is part of a running output patch.",
      "target": {
        "nodeType": "GeneretiAudioOutput",
        "part": "node"
      },
      "hint": "Use Start on the output, not Queue or the lesson Play button."
    },
    {
      "title": "Read the waveform",
      "text": "mod.scope draws left and right waveforms. Its channels output carries sampled stereo data; image carries the drawing. RMS and peak sockets are scalar controls.",
      "target": {
        "nodeType": "GeneretiAudioScope",
        "part": "node"
      },
      "hint": "Increase display_gain to enlarge the drawing without changing sound.",
      "actions": [
        {
          "kind": "set-widget",
          "target": {
            "nodeType": "GeneretiAudioScope",
            "widget": "display_gain",
            "part": "parameter"
          },
          "value": 12
        }
      ]
    },
    {
      "title": "Read the spectrum",
      "text": "mod.spectrum draws decibels on a linear-frequency axis. Channels are magnitude and frequency in Hz. fft_size trades frequency detail for a longer analysis window; smoothing affects spectral bins only.",
      "target": {
        "nodeType": "GeneretiAudioSpectrum",
        "part": "node"
      },
      "hint": "The frequency of bin i is i × sampleRate / fft_size.",
      "actions": [
        {
          "kind": "set-widget",
          "target": {
            "nodeType": "GeneretiAudioSpectrum",
            "widget": "fft_size",
            "part": "parameter"
          },
          "value": 2048
        }
      ]
    },
    {
      "title": "See stereo relationships",
      "text": "mod.lissajous plots left versus right. A centered mono signal forms a diagonal. Change pan to stretch it; richer stereo effects can create loops. Correlation is +1 for identical signals, -1 for opposite phase.",
      "target": {
        "nodeType": "GeneretiAudioLissajous",
        "part": "node"
      },
      "hint": "Pan changes balance, not phase; it will tilt a line rather than generate a loop.",
      "actions": [
        {
          "kind": "set-widget",
          "target": {
            "nodeType": "GeneretiAudioGain",
            "widget": "pan",
            "part": "parameter"
          },
          "value": 0.5
        }
      ]
    },
    {
      "title": "Use analysis as controls",
      "text": "mod.analyze exposes rms, peak, correlation and low/mid/high spectral band amplitudes. chop.select chooses rms, chop.math multiplies it by 12, and its FLOAT output drives the opacity of the scope image in top.filter.",
      "target": {
        "nodeType": "GeneretiChopMath",
        "part": "node"
      },
      "hint": "Follow channels → select rms → math → FLOAT amount. These are control-rate measurements, not an audio-rate CHOP DSP engine.",
      "actions": [
        {
          "kind": "set-widget",
          "target": {
            "nodeType": "GeneretiChopMath",
            "widget": "value",
            "part": "parameter"
          },
          "value": 20
        }
      ]
    },
    {
      "title": "Stop and save",
      "text": "Press ■ Panic on mod.output. Analysis and scalar controls return to zero. Save retains wiring and settings, never a playing AudioContext.",
      "target": {
        "nodeType": "GeneretiAudioOutput",
        "part": "node"
      },
      "hint": "Queue returns silent analysis data and placeholder IMAGEs; the browser owns live analysis."
    }
  ]
}

widgets_values_named.guide:
{
  "format": "genereti-guide",
  "version": 1,
  "id": "opentouch-basics",
  "title": "Textures, signals and tables",
  "summary": "Edit an expression, connect a control signal, and use a table as a parameter source.",
  "steps": [
    {
      "title": "One graph, three interfaces",
      "text": "TOP carries images, CHOP carries sampled channels, and DAT carries documents and tables. The lesson workflow uses real nodes you can keep editing.",
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "node"
      }
    },
    {
      "title": "Write a texture expression",
      "text": "Change the expression, for example change x*12 to x*8. CodeMirror applies it while typing. The GPU program recompiles only when its source changes.",
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "code",
        "widget": "expression"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "Change a signal",
      "text": "Adjust oscillator frequency. The FLOAT output is the last sample of its first channel; the channel output carries the whole named block.",
      "target": {
        "nodeType": "GeneretiChopOscillator",
        "part": "parameter",
        "widget": "frequency"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "A FLOAT becomes a texture control",
      "text": "Follow the wire from chop.lag to top.transform rotate. These are regular Comfy input sockets; signals update the live shader without a Python queue.",
      "target": {
        "nodeType": "GeneretiTextureTransform",
        "part": "node"
      },
      "check": {
        "kind": "connected-input",
        "input": "rotate"
      }
    },
    {
      "title": "A table becomes a parameter",
      "text": "Edit a number in the table. dat.cell selects one cell and exposes it as STRING and FLOAT. The lesson wires its FLOAT into top.math value.",
      "target": {
        "nodeType": "GeneretiDatTable",
        "part": "code",
        "widget": "text"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "GPU composition and history",
      "text": "Inspect feedback, corner pin and compositing. Feedback keeps two GPU textures and avoids cyclic graph wires. Its history exists in Live mode; Queue returns the current input.",
      "target": {
        "nodeType": "GeneretiTextureFeedback",
        "part": "preview"
      }
    },
    {
      "title": "Keep 3D in Three.js",
      "text": "The Three.js Livecode source uses the same IMAGE path. Its code can read inputTexture and declared CHOP-driven parameters; no separate geometry engine is needed.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "part": "code"
      }
    },
    {
      "title": "Read and export the report",
      "text": "The DAT document contains the library report. Use its export controls for Markdown, standalone HTML, or Print / Save as PDF. The report describes performance and device boundaries.",
      "target": {
        "nodeType": "GeneretiDatText",
        "part": "toolbar"
      }
    }
  ]
}
